import { data, TakaroUserError } from '@takaro/helpers';
import { deliverPrivate, getPlayerName, getPrefix, parseText } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod, chatMessage } = data;
  const cfg = mod.userConfig;

  const target = args.player;
  if (!target || !target.playerId) throw new TakaroUserError('Please name a player to message.');

  const text = parseText(chatMessage?.msg, 2, args.message, cfg.maxMessageLength);
  if (!text) throw new TakaroUserError('Please write a message.');

  const [prefix, targetName] = await Promise.all([
    getPrefix(gameServerId),
    getPlayerName(target.playerId, target.name || 'that player'),
  ]);
  const error = await deliverPrivate({
    gameServerId,
    moduleId: mod.moduleId,
    cfg,
    senderPog: pog,
    senderName: player.name,
    target: { playerId: target.playerId, name: targetName },
    text,
    prefix,
    now: Date.now(),
  });
  if (error) throw new TakaroUserError(error);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { deliverPrivate, getPrefix, KEYS, parseText, readVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod, chatMessage } = data;
  const cfg = mod.userConfig;

  const [prefix, reply] = await Promise.all([
    getPrefix(gameServerId),
    readVar(gameServerId, mod.moduleId, player.id, KEYS.replyTo, null),
  ]);
  const last = reply.value;
  if (!last || !last.playerId) {
    throw new TakaroUserError(`Nobody has messaged you yet. Use ${prefix}msg <player> <text>.`);
  }

  const text = parseText(chatMessage?.msg, 1, args.message, cfg.maxMessageLength);
  if (!text) throw new TakaroUserError('Please write a message.');

  const error = await deliverPrivate({
    gameServerId,
    moduleId: mod.moduleId,
    cfg,
    senderPog: pog,
    senderName: player.name,
    target: { playerId: last.playerId, name: last.name },
    text,
    prefix,
    now: Date.now(),
  });
  if (error) throw new TakaroUserError(error);
}

await main();

import { data, TakaroUserError, takaro } from '@takaro/helpers';
import {
  checkCooldown,
  getPlayerName,
  getPrefix,
  isIgnoredBy,
  KEYS,
  loadMailbox,
  parseText,
  pushMail,
  renderTemplate,
  sendTo,
  spyCopy,
  stampCooldown,
  writeVar,
} from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod, chatMessage } = data;
  const cfg = mod.userConfig;
  const moduleId = mod.moduleId;
  const now = Date.now();

  const target = args.player;
  if (!target || !target.playerId) throw new TakaroUserError('Please name a player to mail.');

  const text = parseText(chatMessage?.msg, 2, args.message, cfg.maxMessageLength);
  if (!text) throw new TakaroUserError('Please write a message.');

  const self = target.playerId === player.id;
  const [prefix, targetName] = await Promise.all([
    getPrefix(gameServerId),
    self ? Promise.resolve(player.name) : getPlayerName(target.playerId, target.name || 'that player'),
  ]);

  if (!self && (await isIgnoredBy(gameServerId, moduleId, target.playerId, pog))) {
    throw new TakaroUserError(`${targetName} is not accepting your messages.`);
  }

  const cooldown = await checkCooldown(gameServerId, moduleId, player.id, cfg.cooldownSeconds, now);
  if (cooldown && cooldown.wait) {
    throw new TakaroUserError(`Slow down: wait ${cooldown.wait}s before sending another message.`);
  }

  const box = await loadMailbox(gameServerId, moduleId, target.playerId, cfg.mailExpiryDays, now);
  const mail = { fromId: player.id, fromName: player.name, text, sentAt: new Date(now).toISOString(), read: false };
  const pushed = pushMail(box.mails, mail, cfg.mailboxSize);
  if (!pushed.ok) throw new TakaroUserError(`${targetName}'s mailbox is full. Try again later.`);
  await writeVar(gameServerId, moduleId, target.playerId, KEYS.mailbox, box.id, pushed.mails);
  await stampCooldown(gameServerId, moduleId, player.id, cooldown, now);

  const unread = pushed.mails.filter((m) => !m.read).length;
  let online = false;
  if (!self) {
    try {
      const res = await takaro.playerOnGameserver.playerOnGameServerControllerGetOne(gameServerId, target.playerId);
      const tPog = res.data.data;
      online = Boolean(tPog.online);
      if (online) {
        await sendTo(
          gameServerId,
          tPog.gameId,
          renderTemplate(cfg.newMailNotice, { sender: player.name, count: unread, prefix }),
        );
      }
    } catch (err) {
      console.error(`private-messages: new-mail notice failed: ${err}`);
    }
  }

  await pog.pm(
    online
      ? `Mail sent to ${targetName}. They are online and were told about it.`
      : `Mail sent to ${targetName}. They will get it when they next join.`,
  );
  if (!self) {
    await spyCopy(gameServerId, moduleId, cfg, [player.id, target.playerId], `${player.name} -> ${targetName} (mail): ${text}`);
  }
}

await main();

import { data } from '@takaro/helpers';
import { formatMail, getPrefix, KEYS, loadMailbox, writeVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, module: mod } = data;
  const cfg = mod.userConfig;
  const now = Date.now();

  const [prefix, box] = await Promise.all([
    getPrefix(gameServerId),
    loadMailbox(gameServerId, mod.moduleId, player.id, cfg.mailExpiryDays, now),
  ]);
  if (!box.mails.length) {
    await pog.pm('Your mailbox is empty.');
    if (box.id && box.pruned) await writeVar(gameServerId, mod.moduleId, player.id, KEYS.mailbox, box.id, []);
    return;
  }

  const unread = box.mails.filter((m) => !m.read).length;
  await pog.pm(`Mailbox: ${box.mails.length}/${cfg.mailboxSize} mails, ${unread} new.`);
  for (const mail of box.mails) {
    await pog.pm(`${mail.read ? '' : '[new] '}${formatMail(mail, now)}`);
  }
  await pog.pm(`Type ${prefix}mailclear to empty your mailbox.`);

  if (unread || box.pruned) {
    const updated = box.mails.map((m) => ({ ...m, read: true }));
    await writeVar(gameServerId, mod.moduleId, player.id, KEYS.mailbox, box.id, updated);
  }
}

await main();

import { data } from '@takaro/helpers';
import { deleteVar, KEYS, readVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, module: mod } = data;
  const box = await readVar(gameServerId, mod.moduleId, player.id, KEYS.mailbox, []);
  const count = Array.isArray(box.value) ? box.value.length : 0;
  await deleteVar(box.id);
  await pog.pm(count ? `Deleted ${count} mail${count === 1 ? '' : 's'}.` : 'Your mailbox was already empty.');
}

await main();

import { data, TakaroUserError, takaro } from '@takaro/helpers';
import { formatAgo, getPlayerName } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args } = data;
  const target = args.player;
  if (!target || !target.playerId) throw new TakaroUserError('Please name a player.');
  if (target.playerId === player.id) {
    await pog.pm('You are right here.');
    return;
  }

  const [name, res] = await Promise.all([
    getPlayerName(target.playerId, target.name || 'That player'),
    takaro.playerOnGameserver.playerOnGameServerControllerGetOne(gameServerId, target.playerId),
  ]);
  const tPog = res.data.data;
  if (tPog.online) {
    await pog.pm(`${name} is online right now.`);
    return;
  }
  const lastSeen = tPog.lastSeen ? new Date(tPog.lastSeen) : null;
  if (!lastSeen || Number.isNaN(lastSeen.getTime())) {
    await pog.pm(`${name} has not been seen on this server yet.`);
    return;
  }
  const stamp = lastSeen.toISOString().slice(0, 16).replace('T', ' ');
  await pog.pm(`${name} was last seen ${formatAgo(Date.now() - lastSeen.getTime())} (${stamp} UTC).`);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { addIgnore, getPrefix, KEYS, loadIgnore, resolvePlayerByName, writeVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const input = String(args.player ?? '').trim();
  const ignore = await loadIgnore(gameServerId, mod.moduleId, player.id);

  // Takaro needs a non-empty default for an optional argument, so a bare `ignore` arrives as "list".
  if (!input || input.toLowerCase() === 'list') {
    const prefix = await getPrefix(gameServerId);
    if (!ignore.list.length) {
      await pog.pm(`You are not ignoring anyone. Use ${prefix}ignore <player> to block their messages.`);
      return;
    }
    await pog.pm(`Ignored (${ignore.list.length}): ${ignore.list.map((e) => e.name).join(', ')}`);
    await pog.pm(`Use ${prefix}unignore <player> to allow them again.`);
    return;
  }

  const found = await resolvePlayerByName(gameServerId, input);
  if (found.error) throw new TakaroUserError(found.error);
  if (found.playerId === player.id) throw new TakaroUserError('You cannot ignore yourself.');

  const result = addIgnore(ignore.list, { playerId: found.playerId, name: found.name });
  if (result.full) throw new TakaroUserError('Your ignore list is full. Remove someone with unignore first.');
  if (!result.added) {
    await pog.pm(`You are already ignoring ${found.name}.`);
    return;
  }
  await writeVar(gameServerId, mod.moduleId, player.id, KEYS.ignore, ignore.id, result.list);
  await pog.pm(`You now ignore ${found.name}. Their private messages and mail are blocked.`);
}

await main();

import { data, TakaroUserError } from '@takaro/helpers';
import { deleteVar, KEYS, loadIgnore, writeVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, arguments: args, module: mod } = data;
  const input = String(args.player ?? '').trim().toLowerCase();
  if (!input) throw new TakaroUserError('Please name the player to unignore, or "all".');

  const ignore = await loadIgnore(gameServerId, mod.moduleId, player.id);
  if (input === 'all') {
    await deleteVar(ignore.id);
    await pog.pm(ignore.list.length ? `You no longer ignore anyone (${ignore.list.length} removed).` : 'You were not ignoring anyone.');
    return;
  }

  const exact = ignore.list.filter((e) => String(e.name).toLowerCase() === input);
  const partial = ignore.list.filter((e) => String(e.name).toLowerCase().includes(input));
  const matches = exact.length ? exact : partial;
  if (!matches.length) throw new TakaroUserError(`"${args.player}" is not on your ignore list.`);
  if (matches.length > 1) throw new TakaroUserError(`Several ignored players match "${args.player}". Please type more of the name.`);

  const rest = ignore.list.filter((e) => e.playerId !== matches[0].playerId);
  if (rest.length) {
    await writeVar(gameServerId, mod.moduleId, player.id, KEYS.ignore, ignore.id, rest);
  } else {
    await deleteVar(ignore.id);
  }
  await pog.pm(`You no longer ignore ${matches[0].name}.`);
}

await main();

import { data, TakaroUserError, checkPermission } from '@takaro/helpers';
import { deleteVar, KEYS, readVar, writeVar } from './pm-helpers.js';

async function main() {
  const { pog, player, gameServerId, module: mod } = data;
  if (!mod.userConfig.socialSpy) {
    throw new TakaroUserError('Social spy is turned off on this server.');
  }
  if (!checkPermission(pog, 'PM_SPY')) {
    throw new TakaroUserError('You do not have permission to use social spy.');
  }

  const current = await readVar(gameServerId, mod.moduleId, player.id, KEYS.spy, null);
  if (current.id) {
    await deleteVar(current.id);
    await pog.pm('Social spy OFF. You no longer see copies of private messages.');
  } else {
    await writeVar(gameServerId, mod.moduleId, player.id, KEYS.spy, null, true);
    await pog.pm('Social spy ON. You now see copies of private messages and mail while online.');
  }
}

await main();

